		AtomicInteger closed = new AtomicInteger();
		TripleStore.EnvironmentLifecycle lifecycle = new TripleStore.EnvironmentLifecycle() {
			@Override
			public void afterOpen(long environment) {
			}

			// Intentionally no @Override: this test compiles before the proposed default interface method exists.
			public void sync(long environment) throws IOException {
				assertNull(durableProperties().getRdfTermDomainsVersion(),
						"the old profile is withdrawn before replacement native pages become durable");
				LmdbUtil.E(mdb_env_sync(environment, true));
				throw injected;
			}

			@Override
			public void close(long environment) {
				closed.incrementAndGet();
				mdb_env_close(environment);
			}
		};
		ValueStore values = new ValueStore(directory.resolve("values").toFile(), properties, replacement);
		try (AutoCloseable ownedValues = values::close) {
			IOException failure = assertThrows(IOException.class, () -> {
				try (TripleStore ignored = new TripleStore(directory.resolve("triples").toFile(), properties,
						replacement, values, lifecycle)) {
					// An unsuccessful durability boundary must never return a live writer.
				}
			});
			assertSame(injected, failure);
			assertEquals(1, closed.get(), "constructor failure closes its exact owned triple environment");
			assertNull(properties.getRdfTermDomainsVersion());
			assertNull(durableProperties().getRdfTermDomainsVersion());
		}
		try (Opened opened = open(config(false, true))) {
			DomainQualificationAssertions.verifyCompleteConfiguredCommittedState(opened.store(), opened.repository(),
					opened.config(),
					expected, PREDICATES);
		}
